// CSD_RATIONALE_BEGIN
// This strategy keeps the previous arithmetic-aware shape but repairs the
// verifier issue by avoiding helper-method calls inside boolean expressions.
// Outside constrained spans it generates freely and arms a one-step trigger
// after arithmetic cue tokens so the next action opens a visible "<<"
// computation span. If the model itself emits "<<", the strategy enters the
// observed span without duplicating the delimiter. Inside a span, parser-valid
// decoding is hard authority; very short spans penalize premature closing,
// while longer spans use adaptive group-aware constrained decoding to favor
// arithmetic-like continuations. The strategy closes a span as soon as the
// parser reports completeness.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span free-generation branch,
//   insideConstrainedOut remains false unless we open or observe "<<". Both
//   OpenConstrainedSpan and EnterObservedConstrainedSpan set
//   currentConstrainedOut := [], which is parser-valid by the precondition
//   parser.IsValidPrefix([]). In the complete-prefix branch,
//   CloseConstrainedSpan exits constrained mode, so the implication
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   becomes vacuous. In the active constrained branch, each constrained-step
//   helper returns either EOS or a token that preserves parser validity; on the
//   non-EOS path, AppendConstrainedToken synchronizes generated and
//   currentConstrainedOut while preserving parser validity.
// progress: In the unconstrained branch, UnconstrainedStep consumes one
//   token-step and appends at most one visible token, so
//   |generated| <= |generatedPrefix| + steps is preserved after steps := steps+1.
//   In the forced-open branch, OpenConstrainedSpan consumes one token-step and
//   appends exactly the visible delimiter, again preserving the bound. In the
//   close branch, CloseConstrainedSpan consumes one token-step and appends at
//   most one visible delimiter token. In the constrained branch, the selected
//   constrained-step helper consumes one token-step; EOS may consume budget
//   without visible growth, while AppendConstrainedToken adds at most one
//   visible token on non-EOS, so visible growth never exceeds consumed budget.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var arithmeticArmed: bool := false;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if arithmeticArmed {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      arithmeticArmed := false;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          var observedGenerated, observedInside, observedCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := observedGenerated;
          insideConstrainedOut := observedInside;
          currentConstrainedOut := observedCurrent;
          arithmeticArmed := false;
        } else if next == "=" || next == "+" || next == "-" || next == "*" || next == "/" {
          arithmeticArmed := true;
        } else {
          arithmeticArmed := false;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    arithmeticArmed := false;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nextConstrained := eosToken;
    var eqCount := helpers.CountTokenOccurrences(generated, "=");
    var plusCount := helpers.CountTokenOccurrences(generated, "+");
    var minusCount := helpers.CountTokenOccurrences(generated, "-");
    var timesCount := helpers.CountTokenOccurrences(generated, "*");
    var divCount := helpers.CountTokenOccurrences(generated, "/");
    var hasArithmeticContext: bool := false;
    if eqCount > 0 {
      hasArithmeticContext := true;
    } else if plusCount > 0 {
      hasArithmeticContext := true;
    } else if minusCount > 0 {
      hasArithmeticContext := true;
    } else if timesCount > 0 {
      hasArithmeticContext := true;
    } else if divCount > 0 {
      hasArithmeticContext := true;
    }

    if |currentConstrainedOut| < 2 {
      nextConstrained := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, [">>"], 6.0, eosToken
      );
    } else if hasArithmeticContext {
      nextConstrained := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    } else {
      nextConstrained := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 2.0, eosToken
      );
    }
    steps := steps + 1;
    if nextConstrained == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, nextConstrained
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;
